def ttl_cache(func, maxsize, ttl, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    @wraps(func)
    def ttl_cache_fn(*args, **kwargs):
        key = (args, frozenset(kwargs))
        if key not in cache:
            result = func(*args, **kwargs)
            cache[key] = result, timer()
        else:
            result = cache[key][0]
            if typed and type(result) is not type(args[0]):
                result = cache[key][0] = func(*args, **kwargs)
        if cache[key][1] + ttl <= timer():
            raise KeyError("Entry has expired")
        return result
    return ttl_cache_fn(func)

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        cache_order = []
        def wrapper(*args, **kwargs):
            key = str(args)
            if typed:
                key += str(kwargs)
            if key in cache:
                cache_order.remove(key)
                cache_order.appendleft(key)
                return cache[key]
            if len(cache_order) >= maxsize:
