def format(self, sql, params):
    # Convert in-style parameters to out-style parameters
    if self.in_style == InStyle.named:
        # If in-style parameters are named, iterate through the named parameters and create a dictionary with the name as the key and the value as the value
        new_params = {}
        for name, value in params.items():
            new_params[name] = value
    elif self.in_style == InStyle.ordinal:
        # If in-style parameters are ordinal, iterate through the tuple and create a list with the values
        new_params = list(params)
    else:
        # Raise ValueError if in-style parameters are set to an invalid value
        raise ValueError("In-style parameters are not set to a valid value")

    # Replace all in-style parameters with their corresponding out-style parameters in the SQL query
    for i, param in enumerate(new_params):
        # If the parameter is a string, quote it using %s for postgres and ? for sqlite
        # If the parameter is not a string, treat it as a raw SQL expression and do not use quoting
        if isinstance(param, str):
            quote = "%s" if self._dialect == "postgres" else "?"
            sql = sql.replace("?", quote, 1)
        else:
            sql = sql.replace("?", param, 1)

    return (sql, new_params)

