def check_digests_present_and_used(self, manifest_files, digests_used):
    for manifest_file in manifest_files:
        if manifest_file not in digests_used:
            raise ValueError(f"{manifest_file} is not used anywhere")

    digests_needed = []
    digests_missing = []
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            manifest = json.load(f)
            for digest in manifest["digests"]:
                if digest not in digests_used:
                    digests_needed.append(digest)

    for digest in digests_needed:
        if digest not in manifest_files:
            digests_missing.append(digest)

    if len(digests_missing) > 0:
        raise ValueError(f"The following digests are needed but missing: {', '.join(digests_missing)}")

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Expected an InventoryValidator object, got {}".format(type(prior)))

    if prior.version < self.version:
        raise ValueError("Can only validate prior versions")

    for k, v in self.items():
        if k not in prior:
            raise ValueError("Inventory key {} not found in prior".format(k))
        if prior[k] != v:
            raise ValueError("Inventory value for key {} differed in prior ({}) and current ({})".format(k, prior[k], v))

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for item, path_in_state in inventory.items():
        content_files = set(item.content_files)
        if not version or version == this_version:
            logical_path_map[path_in_state] = content_files
        elif version > this_version:
            logical_path_map[path_in_state] = content_files.difference(inventory.get(next_version, {}).get(path_in_state, set()))
        else:
            logical_path_map[path_in_state] = content_files.intersection(inventory.get(last_version, {}).get(path_in_state, set()))
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    # Verify that the fixity block is provided
    if fixity is None:
        raise ValueError("No fixity block provided")

    # Verify that the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block is not a dictionary")

    # Verify that only files listed in the manifest are referenced
    for file_name in fixity.keys():
        if file_name not in manifest_files:
            raise ValueError(f"File {file_name} is not listed in manifest")

    # Verify that there is a "method" key with the correct value
    if "method" not in fixity or fixity["method"] not in {"sha256", "md5"}:
        raise ValueError("Invalid method value")

    # Verify that there is a "hash" key with the correct value
    if "hash" not in fixity or not isinstance(fixity["hash"], str):
        raise ValueError("Invalid hash value")

    # Verify that there is no extraneous data in the fixity block
    if len(fixity.keys()) != 3:
        raise ValueError("Extraneous data found in fixity block")

