def absorb(self, args):
    new_args = []
    for expr in args:
        abs_expr1 = None
        abs_expr2 = None
        if isinstance(expr, Or):
            for term in expr.terms:
                if isinstance(term, And):
                    abs_expr1 = And(*(term.terms))
                    break
            for term in expr.terms:
                if isinstance(term, Or):
                    abs_expr2 = Or(*(term.terms))
                    break
            if abs_expr1 and abs_expr2:
                new_args.append(abs_expr1)
        elif isinstance(expr, And):
            for term in expr.terms:
                if isinstance(term, Or):
                    abs_expr1 = Or(*(term.terms))
                    break
            for term in expr.terms:
                if isinstance(term, And):
                    abs_expr2 = And(*(term.terms))
                    break
            if abs_expr1 and abs_expr2:
                new_args.append(abs_expr2)
        else:
            new_args.append(expr)
    return and_(*new_args) if len(new_args) > 1 else new_args[0]

