def next_version(version):
    def next_non_zero_digit(digit):
        if digit == 9:
            return 0
        else:
            return digit + 1

    def next_non_zero_digit_index(version, start_index):
        for index in range(start_index, len(version)):
            if version[index] != 0:
                return index
        return None

    def digit_at(version, index):
        return version[index]

    def increment_version(version):
        non_zero_index = next_non_zero_digit_index(version, 0)
        if non_zero_index is None:
            version.insert(0, 1)
        else:
            non_zero_digit = digit_at(version, non_zero_index)
            next_digit = next_non_zero_digit(non_zero_digit)
            version[non_zero_index] = next_digit
            if next_digit == 0:
                for index in range(non_zero_index + 1, len(version)):
                    if version[index] != 0:
                        break
                else:
                    version.append(1)

        return version

    return '.'.join(str(s) for s in increment_version(version.split('.'))).strip()

def validate_version_inventories(self, version_dirs):
    # Keep track of the root inventory content digests throughout iterations
    root_inventory_digests = {}
    # Keep track of different content digests in each version to validate
    version_digests = {}
    # Iterate over each version directory
    for version_dir in version_dirs:
        # Read the inventory file for the current version
        inventory_file = os.path.join(version_dir, "inventory.json")
        with open(inventory_file, "r") as f:
            inventory = json.load(f)
        # Check if the inventory is valid
        if not self.validate_inventory(inventory):
            raise ValueError(f"Inventory for version {version_dir} is invalid")
        # Add the content digests to the root inventory digests
        for content in inventory:
            digest = self.hash_content(content["content"])
            root_inventory_digests[digest] = content
        # Add the content digests to the version digests
        version_digests[version_dir] = [
            self.hash_content(content["content"])
            for content in inventory
        ]
    # Check if the content digests are in the root inventory digests
    for version_dir, digests in version_digests.items():
        for digest in digests:
            if digest not in root_inventory_digests:
                raise ValueError(
                    f"Content for version {version_dir} not found in root inventory"
                )
    # Return the version digests
    return version_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isfile(path):
        with open(path, 'r') as f:
            data = json.loads(f.read())
            if 'stmts' in data:
                return 'object'
            elif 'invent' in data:
                return 'file'
        raise FileNotFoundError("The specified file does not seem to be an OCFL object or file")

    if os.path.isdir(path):
        for file in os.listdir(path):
            if file.startswith('0=') and file.endswith('.namaste'):
                with open(file, 'r') as f:
                    data = json.loads(f.read())
                    if 'root: ' in data:
                        return 'root'
                    else:
                        raise FileNotFoundError("The specified directory does not seem to contain an OCFL root file")
        raise FileNotFoundError("The specified directory does not contain any OCFL objects or files")
    raise FileNotFoundError("The specified path does not seem to be a file or directory")

