def deep_merge_nodes(nodes):
    if not nodes:
        return

    nodes = sorted(nodes, key=lambda n: n[0].value)
    merged_nodes = []

    for node in nodes:
        if not merged_nodes or node[0] != merged_nodes[-1][0]:
            merged_nodes.append(node)
        else:
            merged_nodes[-1][1] = deep_merge_nodes(
                [merged_nodes[-1][1], node[1]]
            )

    return merged_nodes


