def size_to_bytes(size: str) -> int:
    if size.isdigit():
        return int(size)
    if size.endswith("K"):
        return int(float(size[:-1]) * 1000)
    if size.endswith("M"):
        return int(float(size[:-1]) * 1000000)
    if size.endswith("G"):
        return int(float(size[:-1]) * 1000000000)
    raise ValueError("Invalid input format")

