    for subclass in cls.__subclasses__():
        subclasses.append(subclass)
        subclasses.extend(subclasses(subclasses))
    return subclasses

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not isinstance(string, str):
        raise TypeError("Argument 'string' must be a string.")
    if not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise TypeError("Argument 'alphabet' must be a list of strings.")

    if len(string) == 0:
        return 0

    result = 0
    for i, c in enumerate(reversed(string)):
        index = alphabet.index(c)
        result += index * (len(alphabet) ** i)

    return result

