def split(s, platform='this'):
    if platform == 'this':
        if os.name == 'posix':
            posix_split = shlex.split(s)
            return posix_split
        else:
            win_split = _win_cmd_split(s)
            return win_split
    elif platform == '1':
        posix_split = shlex.split(s)
        return posix_split
    elif platform == '0':
        win_split = _win_cmd_split(s)
        return win_split
    else:
        msg = "Invalid platform argument. Must be 'this', '1', or '0'. " \
              "Got '{}'.".format(platform)
        raise ValueError(msg)

def _win_cmd_split(s):
    # separate args with Regex for more control
    regex = r'[^()"]+|(\([^)]*\))+|"[^"]*"'
    args = regex.findall(s)
    args = [arg.strip() for arg in args]
    return [arg for arg in args if arg]

import datetime

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    frequency_pattern = r"(\d+)\s*([a-z]+)"
    match = re.fullmatch(frequency_pattern, frequency)
    if not match:
        raise ValueError(f"Invalid frequency: {frequency}")

    number, unit = match.groups()
    if unit == "weeks":
        return datetime.timedelta(weeks=int(number))
    elif unit == "days":
        return datetime.timedelta(days=int(number))
    elif unit == "hours":
        return datetime.timedelta(hours=int(number))
    elif unit == "minutes":
        return datetime.timedelta(minutes=int(number))
    elif unit == "seconds":
        return datetime.timedelta(seconds=int(number))
    else:
        raise ValueError(f"Invalid unit: {unit}")

