import re

def make_find_paths_impl(find_paths):
    glob_pattern, is_pattern = [], False
    for path in find_paths:
        if re.match(r"^[a-zA-Z]+:", path):
            is_pattern = True
        if not is_pattern:
            glob_pattern.append(f"sh:**/*{re.escape(path)}" + "/**")
        else:
            glob_pattern.append(path)
    return glob_pattern

