def _resolve_string(matcher):
    resolved = ''
    name = matcher.get('name')
    if name:
        resolved = os.environ.get(name)
        if not resolved:
            resolved = matcher.get('default')
    if not resolved:
        if matcher.get('default'):
            resolved = matcher.get('default')
        else:
            raise ValueError("Missing required value for parameter 'name'")
    return resolved

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    match = re.search(r'//(?P<netloc>[^/]*)/(?P<image_id>[^/]*)', image_href)
    if not match:
        raise ValueError(f'Invalid image href: {image_href}')
    use_ssl = True if image_href.startswith('https') else False
    return (match.group('image_id'), match.group('netloc'), use_ssl)

