def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not commands:
        raise ValueError("At least one command must be provided")
    if args is None:
        args = []
    if cwd is None:
        cwd = os.getcwd()
    env = {} if env is None else env

    commands = commands + args
    try:
        process = subprocess.run(commands, cwd=cwd, env=env, check=True)
    except subprocess.CalledProcessError as e:
        if hide_stderr:
            stdout = e.output + "\nCommand returned with error code " + str(e.returncode)
        else:
            stdout = e.output + "\nCommand returned with error code " + str(e.returncode) + " and stderr:\n" + e.stderr
        if verbose:
            print(stdout)
        return stdout
    else:
        stdout = process.stdout + "\nCommand returned with success"
        if verbose:
            print(stdout)
        return stdout

